import ctypes
import numpy as np
import numba as nb
from numba.extending import get_cython_function_address as _gcfa
from scipy import sparse

_VP = ctypes.c_void_p
_dlahqr = ctypes.CFUNCTYPE(None, *([_VP] * 14))(_gcfa("scipy.linalg.cython_lapack", "dlahqr"))
_dtrevc = ctypes.CFUNCTYPE(None, *([_VP] * 14))(_gcfa("scipy.linalg.cython_lapack", "dtrevc"))
_dlartg = ctypes.CFUNCTYPE(None, *([_VP] * 5))(_gcfa("scipy.linalg.cython_lapack", "dlartg"))
_dlarfg = ctypes.CFUNCTYPE(None, *([_VP] * 5))(_gcfa("scipy.linalg.cython_lapack", "dlarfg"))

EPS = 2.220446049250313e-16
ULP = 2.220446049250313e-16
UNFL = 2.2250738585072014e-308
EPS23 = EPS ** (2.0 / 3.0)


@nb.njit(inline='always')
def dlapy2(x, y):
    xa = abs(x)
    ya = abs(y)
    w = max(xa, ya)
    z = min(xa, ya)
    if z == 0.0:
        return w
    return w * np.sqrt(1.0 + (z / w) ** 2)


@nb.njit
def dsortc(which, n, xr, xi, y):
    # 0: 'LM' -> increasing magnitude; 2: 'LR' -> increasing real; 3: 'SR' -> decreasing real
    igap = n // 2
    while igap != 0:
        for i in range(igap, n):
            j = i - igap
            while j >= 0:
                if which == 0:
                    sw = dlapy2(xr[j], xi[j]) > dlapy2(xr[j + igap], xi[j + igap])
                elif which == 2:
                    sw = xr[j] > xr[j + igap]
                else:
                    sw = xr[j] < xr[j + igap]
                if not sw:
                    break
                t = xr[j]; xr[j] = xr[j + igap]; xr[j + igap] = t
                t = xi[j]; xi[j] = xi[j + igap]; xi[j + igap] = t
                t = y[j]; y[j] = y[j + igap]; y[j + igap] = t
                j -= igap
        igap //= 2


@nb.njit
def dngets(ishift, kev, np_, rr, ri, bd):
    n = kev + np_
    dsortc(2, n, rr, ri, bd)
    dsortc(0, n, rr, ri, bd)
    if (rr[np_] - rr[np_ - 1]) == 0.0 and (ri[np_] + ri[np_ - 1]) == 0.0:
        np_ -= 1
        kev += 1
    if ishift == 1:
        dsortc(3, np_, bd, rr, ri)
    return kev, np_


@nb.njit
def dlanhs1(H, n):
    best = 0.0
    for j in range(n):
        s = 0.0
        for i in range(min(n, j + 2)):
            s += abs(H[i, j])
        if s > best:
            best = s
    return best


@nb.njit
def matvec(indptr, indices, data, x, y):
    n = y.shape[0]
    for i in range(n):
        s = 0.0
        for jj in range(indptr[i], indptr[i + 1]):
            s += data[jj] * x[indices[jj]]
        y[i] = s



@nb.njit(fastmath=True)
def _dots(V, m, x, out):
    n = x.shape[0]
    for l in range(m):
        vl = V[l]
        s = 0.0
        for i in range(n):
            s += vl[i] * x[i]
        out[l] = s


@nb.njit(fastmath=True)
def _sub_comb(V, m, c, x):
    n = x.shape[0]
    for l in range(m):
        vl = V[l]
        cl = c[l]
        for i in range(n):
            x[i] -= cl * vl[i]


@nb.njit(fastmath=True)
def _comb(V, m, Q, col, out):
    n = out.shape[0]
    for i in range(n):
        out[i] = 0.0
    for l in range(m):
        cl = Q[l, col]
        if cl != 0.0:
            vl = V[l]
            for i in range(n):
                out[i] += cl * vl[i]


@nb.njit(fastmath=True)
def nrm2(x):
    s = 0.0
    for i in range(x.shape[0]):
        s += x[i] * x[i]
    return np.sqrt(s)

@nb.njit
def dnaitr(indptr, indices, data, k, np_, resid, rnorm, V, H, w, tmp):
    """Extend Arnoldi factorization from k to k+np_ steps. V rows are basis vectors."""
    n = resid.shape[0]
    smlnum = UNFL * (n / ULP)
    j = k
    while j < k + np_:
        betaj = rnorm
        if rnorm <= 0.0:
            return -1.0  # breakdown: not handled
        inv = 1.0 / rnorm
        vj = V[j]
        for i in range(n):
            vj[i] = resid[i] * inv
        matvec(indptr, indices, data, vj, w)
        for i in range(n):
            resid[i] = w[i]
        wnorm = nrm2(resid)
        # CGS: h(0:j+1, j) = V^T w
        _dots(V, j + 1, w, tmp)
        for l in range(j + 1):
            H[l, j] = tmp[l]
        _sub_comb(V, j + 1, tmp, resid)
        if j > 0:
            H[j, j - 1] = betaj
        rnorm = nrm2(resid)
        if rnorm <= 0.717 * wnorm:
            it = 0
            while True:
                _dots(V, j + 1, resid, tmp)
                _sub_comb(V, j + 1, tmp, resid)
                for l in range(j + 1):
                    H[l, j] += tmp[l]
                rnorm1 = nrm2(resid)
                if rnorm1 > 0.717 * rnorm:
                    rnorm = rnorm1
                    break
                rnorm = rnorm1
                it += 1
                if it <= 1:
                    continue
                for i in range(n):
                    resid[i] = 0.0
                rnorm = 0.0
                break
        j += 1
    kp = k + np_
    for i in range(max(1, k) - 1, kp - 1):
        tst1 = abs(H[i, i]) + abs(H[i + 1, i + 1])
        if tst1 == 0.0:
            tst1 = dlanhs1(H, kp)
        if abs(H[i + 1, i]) <= max(ULP * tst1, smlnum):
            H[i + 1, i] = 0.0
    return rnorm


@nb.njit
def dneigh(rnorm, kp, H, rr, ri, bd, Q, T, work, iv, cR, cB):
    # T := H copy (Fortran layout views)
    for j in range(kp):
        for i in range(kp):
            T[i, j] = H[i, j]
            Q[i, j] = 1.0 if i == j else 0.0
    iv[0] = 1; iv[1] = 1; iv[2] = kp; iv[3] = 1; iv[4] = kp; iv[5] = kp; iv[6] = 0
    _dlahqr(iv[0:].ctypes.data, iv[1:].ctypes.data, iv[2:].ctypes.data, iv[3:].ctypes.data,
            iv[4:].ctypes.data, T.ctypes.data, iv[5:].ctypes.data, rr.ctypes.data, ri.ctypes.data,
            iv[3:].ctypes.data, iv[4:].ctypes.data, Q.ctypes.data, iv[5:].ctypes.data, iv[6:].ctypes.data)
    if iv[6] != 0:
        return -1
    for i in range(kp):
        bd[i] = Q[kp - 1, i]
    iv[7] = 0
    sel = np.zeros(kp, np.int32)
    _dtrevc(cR.ctypes.data, cB.ctypes.data, sel.ctypes.data, iv[2:].ctypes.data, T.ctypes.data,
            iv[5:].ctypes.data, Q.ctypes.data, iv[5:].ctypes.data, Q.ctypes.data, iv[5:].ctypes.data,
            iv[5:].ctypes.data, iv[7:].ctypes.data, work.ctypes.data, iv[6:].ctypes.data)
    if iv[6] != 0:
        return -1
    iconj = 0
    for i in range(kp):
        if abs(ri[i]) <= 0.0:
            s = 0.0
            for l in range(kp):
                s += Q[l, i] ** 2
            t = 1.0 / np.sqrt(s)
            for l in range(kp):
                Q[l, i] *= t
        else:
            if iconj == 0:
                s1 = 0.0
                s2 = 0.0
                for l in range(kp):
                    s1 += Q[l, i] ** 2
                    s2 += Q[l, i + 1] ** 2
                t = 1.0 / dlapy2(np.sqrt(s1), np.sqrt(s2))
                for l in range(kp):
                    Q[l, i] *= t
                    Q[l, i + 1] *= t
                iconj = 1
            else:
                iconj = 0
    for i in range(kp):
        s = 0.0
        for l in range(kp):
            s += Q[l, i] * bd[l]
        work[i] = s
    iconj = 0
    for i in range(kp):
        if abs(ri[i]) <= 0.0:
            bd[i] = rnorm * abs(work[i])
        else:
            if iconj == 0:
                bd[i] = rnorm * dlapy2(work[i], work[i + 1])
                bd[i + 1] = bd[i]
                iconj = 1
            else:
                iconj = 0
    return 0


@nb.njit
def dlarf_left(nr, ncol, u, tau, H, r0, c0):
    # H[r0:r0+nr, c0:c0+ncol] = (I - tau u u^T) H[...]
    if tau == 0.0:
        return
    for j in range(c0, c0 + ncol):
        s = 0.0
        for l in range(nr):
            s += u[l] * H[r0 + l, j]
        s *= tau
        for l in range(nr):
            H[r0 + l, j] -= s * u[l]


@nb.njit
def dlarf_right(nrow, nr, u, tau, H, c0):
    # H[0:nrow, c0:c0+nr] = H[...] (I - tau u u^T)
    if tau == 0.0:
        return
    for i in range(nrow):
        s = 0.0
        for l in range(nr):
            s += H[i, c0 + l] * u[l]
        s *= tau
        for l in range(nr):
            H[i, c0 + l] -= s * u[l]


@nb.njit
def dnapps(n, kev, np_, shr, shi, V, H, resid, Q, w2, wtmp, sc):
    kp = kev + np_
    smlnum = UNFL * (n / ULP)
    for j in range(kp):
        for i in range(kp):
            Q[i, j] = 1.0 if i == j else 0.0
    if np_ == 0:
        return kev
    u = np.zeros(3)
    cconj = False
    for jj in range(np_):
        sigmar = shr[jj]
        sigmai = shi[jj]
        if cconj:
            cconj = False
            continue
        elif jj < np_ - 1 and abs(sigmai) > 0.0:
            cconj = True
        elif jj == np_ - 1 and abs(sigmai) > 0.0:
            kev += 1
            continue
        istart = 0
        while True:
            iend = kp - 1
            for i in range(istart, kp - 1):
                tst1 = abs(H[i, i]) + abs(H[i + 1, i + 1])
                if tst1 == 0.0:
                    tst1 = dlanhs1(H, kp - jj)
                if abs(H[i + 1, i]) <= max(ULP * tst1, smlnum):
                    iend = i
                    H[i + 1, i] = 0.0
                    break
            skip = (istart == iend) or (istart >= kev) or (istart + 1 == iend and abs(sigmai) > 0.0)
            if not skip:
                h11 = H[istart, istart]
                h21 = H[istart + 1, istart]
                if abs(sigmai) <= 0.0:
                    f = h11 - sigmar
                    g = h21
                    for i in range(istart, iend):
                        sc[0] = f; sc[1] = g
                        _dlartg(sc[0:].ctypes.data, sc[1:].ctypes.data, sc[2:].ctypes.data,
                                sc[3:].ctypes.data, sc[4:].ctypes.data)
                        c = sc[2]; s = sc[3]; r = sc[4]
                        if i > istart:
                            if r < 0.0:
                                r = -r; c = -c; s = -s
                            H[i, i - 1] = r
                            H[i + 1, i - 1] = 0.0
                        for j in range(i, kp):
                            t = c * H[i, j] + s * H[i + 1, j]
                            H[i + 1, j] = -s * H[i, j] + c * H[i + 1, j]
                            H[i, j] = t
                        for j in range(min(i + 3, iend + 1)):
                            t = c * H[j, i] + s * H[j, i + 1]
                            H[j, i + 1] = -s * H[j, i] + c * H[j, i + 1]
                            H[j, i] = t
                        for j in range(min(i + jj + 2, kp)):
                            t = c * Q[j, i] + s * Q[j, i + 1]
                            Q[j, i + 1] = -s * Q[j, i] + c * Q[j, i + 1]
                            Q[j, i] = t
                        if i < iend - 1:
                            f = H[i + 1, i]
                            g = H[i + 2, i]
                else:
                    h12 = H[istart, istart + 1]
                    h22 = H[istart + 1, istart + 1]
                    h32 = H[istart + 2, istart + 1]
                    s2 = 2.0 * sigmar
                    t2 = dlapy2(sigmar, sigmai)
                    u[0] = (h11 * (h11 - s2) + t2 * t2) / h21 + h12
                    u[1] = h11 + h22 - s2
                    u[2] = h32
                    for i in range(istart, iend):
                        nr = min(3, iend - i + 1)
                        sc[5] = nr
                        nri = np.empty(2, np.int32)
                        nri[0] = nr; nri[1] = 1
                        _dlarfg(nri[0:].ctypes.data, u[0:].ctypes.data, u[1:].ctypes.data,
                                nri[1:].ctypes.data, sc[6:].ctypes.data)
                        tau = sc[6]
                        if i > istart:
                            H[i, i - 1] = u[0]
                            H[i + 1, i - 1] = 0.0
                            if i < iend - 1:
                                H[i + 2, i - 1] = 0.0
                        u[0] = 1.0
                        dlarf_left(nr, kp - i, u, tau, H, i, i)
                        ir = min(i + 4, iend + 1)
                        dlarf_right(ir, nr, u, tau, H, i)
                        dlarf_right(kp, nr, u, tau, Q, i)
                        if i < iend - 1:
                            u[0] = H[i + 1, i]
                            u[1] = H[i + 2, i]
                            if i < iend - 2:
                                u[2] = H[i + 3, i]
            istart = iend + 1
            if iend >= kp - 1:
                break
    for j in range(kev):
        if H[j + 1, j] < 0.0:
            for l in range(j, kp):
                H[j + 1, l] = -H[j + 1, l]
            for l in range(min(j + 3, kp)):
                H[l, j + 1] = -H[l, j + 1]
            for l in range(min(j + np_ + 2, kp)):
                Q[l, j + 1] = -Q[l, j + 1]
    for i in range(kev):
        tst1 = abs(H[i, i]) + abs(H[i + 1, i + 1])
        if tst1 == 0.0:
            tst1 = dlanhs1(H, kev)
        if H[i + 1, i] <= max(ULP * tst1, smlnum):
            H[i + 1, i] = 0.0
    hk = H[kev, kev - 1]
    if hk > 0.0:
        _comb(V, kp, Q, kev, w2)
    for i in range(kev):
        col = kev - 1 - i
        m = kp - i
        _comb(V, m, Q, col, wtmp)
        V[kp - 1 - i, :] = wtmp
    for i in range(kev):
        V[i, :] = V[kp - kev + i, :]
    if hk > 0.0:
        V[kev, :] = w2
    qs = Q[kp - 1, kev - 1]
    for x in range(n):
        resid[x] *= qs
    if hk > 0.0:
        for x in range(n):
            resid[x] += hk * V[kev, x]
    return kev


@nb.njit
def dnconv(nev, rr, ri, bd, off, tol):
    c = 0
    for i in range(nev):
        temp = max(EPS23, dlapy2(rr[off + i], ri[off + i]))
        if bd[off + i] <= tol * temp:
            c += 1
    return c


@nb.njit
def arnoldi(indptr, indices, data, n, nev0, ncv, maxiter, Hbuf, Qbuf, Tbuf, V, out_rr, out_ri, out_bd):
    tol = EPS
    np0 = ncv - nev0
    kp = ncv
    H = Hbuf.T
    Q = Qbuf.T
    T = Tbuf.T
    resid = np.empty(n)
    w = np.empty(n)
    w2 = np.empty(n)
    tmp = np.empty(ncv)
    work = np.empty(3 * ncv)
    iv = np.zeros(8, np.int32)
    sc = np.zeros(8)
    cR = np.array([ord('R')], np.uint8)
    cB = np.array([ord('A')], np.uint8)
    rr = np.empty(kp); ri = np.empty(kp); bd = np.empty(kp)
    # getv0: resid = OP * ones
    ones = np.ones(n)
    matvec(indptr, indices, data, ones, resid)
    rnorm = nrm2(resid)
    rnorm = dnaitr(indptr, indices, data, 0, nev0, resid, rnorm, V, H, w, tmp)
    if rnorm < 0:
        return -1, 0, 0
    nev = nev0
    it = 0
    while True:
        it += 1
        np_ = kp - nev
        rnorm = dnaitr(indptr, indices, data, nev, np_, resid, rnorm, V, H, w, tmp)
        if rnorm < 0:
            return -1, 0, it
        if dneigh(rnorm, kp, H, rr, ri, bd, Q, T, work, iv, cR, cB) != 0:
            return -1, 0, it
        out_rr[:] = rr; out_ri[:] = ri; out_bd[:] = bd
        nev = nev0
        np_ = np0
        numcnv = nev
        nev, np_ = dngets(1, nev, np_, rr, ri, bd)
        if nev == nev0 + 1:
            numcnv = nev0 + 1
        nconv = dnconv(nev, rr, ri, bd, np_, tol)
        nptemp = np_
        for j in range(nptemp):
            if bd[j] == 0.0:
                np_ -= 1
                nev += 1
        if nconv >= numcnv or it > maxiter or np_ == 0:
            if nconv < numcnv:
                return -2, nconv, it
            return 0, nconv, it
        elif nconv < numcnv:
            nevbef = nev
            nev = nev + min(nconv, np_ // 2)
            if nev == 1 and kp >= 6:
                nev = kp // 2
            elif nev == 1 and kp > 3:
                nev = 2
            if nev > kp - 2:
                nev = kp - 2
            np_ = kp - nev
            if nevbef < nev:
                nev, np_ = dngets(1, nev, np_, rr, ri, bd)
        nev = dnapps(n, nev, np_, rr, ri, V, H, resid, Q, w2, w, sc)
        rnorm = nrm2(resid)


def _arpack_like(A, k, ncv):
    n = A.shape[0]
    indptr = A.indptr.astype(np.int64)
    indices = A.indices.astype(np.int64)
    data = A.data.astype(np.float64)
    Hbuf = np.zeros((ncv, ncv)); Qbuf = np.zeros((ncv, ncv)); Tbuf = np.zeros((ncv, ncv))
    V = np.zeros((ncv, n))
    rr = np.empty(ncv); ri = np.empty(ncv); bd = np.empty(ncv)
    info, nconv, _it = arnoldi(indptr, indices, data, n, k, ncv, n * 200, Hbuf, Qbuf, Tbuf, V, rr, ri, bd)
    if info != 0:
        return None
    H = Hbuf.T.copy()
    # dneupd selection
    rr2 = rr.copy(); ri2 = ri.copy(); idx = np.arange(1, ncv + 1, dtype=np.float64)
    dngets(0, k, ncv - k, rr2, ri2, idx)
    select = np.zeros(ncv, bool)
    numcnv = 0
    for j in range(1, ncv + 1):
        temp1 = max(EPS23, dlapy2(rr2[ncv - j], ri2[ncv - j]))
        jj = int(idx[ncv - j])
        if numcnv < nconv and bd[jj - 1] <= EPS * temp1:
            select[jj - 1] = True
            numcnv += 1
    if numcnv != nconv:
        return None
    pos = np.nonzero(select)[0]
    dvals = rr[pos] + 1j * ri[pos]
    # eigenvectors of H for these eigenvalues
    ew, ev = np.linalg.eig(H)
    vecs = []
    for lam in dvals:
        c = int(np.argmin(np.abs(ew - lam)))
        vecs.append(V.T @ ev[:, c])
    Z = np.array(vecs).T if vecs else np.zeros((n, 0), complex)
    # mimic scipy's post-processing
    nret = nconv
    d = np.zeros(k + 1, complex)
    z = np.zeros((n, k + 1), complex)
    d[:nconv] = dvals
    z[:, :nconv] = Z
    i = 0
    while i <= k:
        if abs(d[i].imag) != 0:
            if i < k:
                i += 1
            else:
                nret -= 1
        i += 1
    if nret <= k:
        d = d[:nret]; z = z[:, :nret]
    else:
        ind = np.argsort(abs(d))[-k:][::-1]
        d = d[ind]; z = z[:, ind]
    return d, z


def _reference(A, k):
    N = A.shape[0]
    v0 = np.ones(N, dtype=A.dtype)
    return sparse.linalg.eigs(A, k=k, v0=v0, maxiter=N * 200, ncv=max(2 * k + 1, 20))


class Solver:
    def solve(self, problem, **kwargs):
        A = problem["matrix"]
        k = problem["k"]
        res = None
        if sparse.isspmatrix_csr(A) or isinstance(A, sparse.csr_array):
            if A.dtype == np.float64 and A.shape[0] > max(2 * k + 1, 20) + 1:
                res = _arpack_like(A, k, max(2 * k + 1, 20))
        if res is None:
            res = _reference(A, k)
        w, v = res
        pairs = list(zip(w, v.T))
        pairs.sort(key=lambda p: -np.abs(p[0]))
        return [p[1] for p in pairs]


