            c = Q[l, col]
            if c != 0.0:
                vl = V[l]
                for x in range(n):
                    wtmp[x] += c * vl[x]
        V[kp - 1 - i, :] = wtmp
    for i in range(kev):
        V[i, :] = V[kp - kev + i, :]
    if hk > 0.0:
        V[kev, :] = w2
    qs = Q[kp - 1, kev - 1]
    for x in range(n):
        resid[x] *= qs
    if hk > 0.0:
        for x in range(n):
            resid[x] += hk * V[kev, x]
    return kev


@nb.njit
def dnconv(nev, rr, ri, bd, off, tol):
    c = 0
    for i in range(nev):
        temp = max(EPS23, dlapy2(rr[off + i], ri[off + i]))
        if bd[off + i] <= tol * temp:
            c += 1
    return c


@nb.njit
def arnoldi(indptr, indices, data, n, nev0, ncv, maxiter, Hbuf, Qbuf, Tbuf, V, out_rr, out_ri, out_bd):
    tol = EPS
    np0 = ncv - nev0
    kp = ncv
    H = Hbuf.T
    Q = Qbuf.T
    T = Tbuf.T
    resid = np.empty(n)
    w = np.empty(n)
    w2 = np.empty(n)
    tmp = np.empty(ncv)
    work = np.empty(3 * ncv)
    iv = np.zeros(8, np.int32)
    sc = np.zeros(8)
    cR = np.array([ord('R')], np.uint8)
    cB = np.array([ord('B')], np.uint8)
    rr = np.empty(kp); ri = np.empty(kp); bd = np.empty(kp)
    # getv0: resid = OP * ones
    ones = np.ones(n)
    matvec(indptr, indices, data, ones, resid)
    rnorm = nrm2(resid)
    rnorm = dnaitr(indptr, indices, data, 0, nev0, resid, rnorm, V, H, w, tmp)
    if rnorm < 0:
        return -1, 0
    nev = nev0
    it = 0
    while True:
        it += 1
        np_ = kp - nev
        rnorm = dnaitr(indptr, indices, data, nev, np_, resid, rnorm, V, H, w, tmp)
        if rnorm < 0:
            return -1, 0
        if dneigh(rnorm, kp, H, rr, ri, bd, Q, T, work, iv, cR, cB) != 0:
            return -1, 0
        out_rr[:] = rr; out_ri[:] = ri; out_bd[:] = bd
        nev = nev0
        np_ = np0
        numcnv = nev
        nev, np_ = dngets(1, nev, np_, rr, ri, bd)
        if nev == nev0 + 1:
            numcnv = nev0 + 1
        nconv = dnconv(nev, rr, ri, bd, np_, tol)
        nptemp = np_
        for j in range(nptemp):
            if bd[j] == 0.0:
                np_ -= 1
                nev += 1
        if nconv >= numcnv or it > maxiter or np_ == 0:
            if nconv < numcnv:
                return -2, nconv
            return 0, nconv
        elif nconv < numcnv:
            nevbef = nev
            nev = nev + min(nconv, np_ // 2)
            if nev == 1 and kp >= 6:
                nev = kp // 2
            elif nev == 1 and kp > 3:
                nev = 2
            if nev > kp - 2:
                nev = kp - 2
            np_ = kp - nev
            if nevbef < nev:
                nev, np_ = dngets(1, nev, np_, rr, ri, bd)
        nev = dnapps(n, nev, np_, rr, ri, V, H, resid, Q, w2, w, sc)
        rnorm = nrm2(resid)


def _arpack_like(A, k, ncv):
    n = A.shape[0]
    indptr = A.indptr.astype(np.int64)
    indices = A.indices.astype(np.int64)
    data = A.data.astype(np.float64)
    Hbuf = np.zeros((ncv, ncv)); Qbuf = np.zeros((ncv, ncv)); Tbuf = np.zeros((ncv, ncv))
    V = np.zeros((ncv, n))
    rr = np.empty(ncv); ri = np.empty(ncv); bd = np.empty(ncv)
    info, nconv = arnoldi(indptr, indices, data, n, k, ncv, n * 200, Hbuf, Qbuf, Tbuf, V, rr, ri, bd)
    if info != 0:
        return None
    H = Hbuf.T.copy()
    # dneupd selection
    rr2 = rr.copy(); ri2 = ri.copy(); idx = np.arange(1, ncv + 1, dtype=np.float64)
    dngets(0, k, ncv - k, rr2, ri2, idx)
    select = np.zeros(ncv, bool)
    numcnv = 0
    for j in range(1, ncv + 1):
        temp1 = max(EPS23, dlapy2(rr2[ncv - j], ri2[ncv - j]))
        jj = int(idx[ncv - j])
        if numcnv < nconv and bd[jj - 1] <= EPS * temp1:
            select[jj - 1] = True
            numcnv += 1
    if numcnv != nconv:
        return None
    pos = np.nonzero(select)[0]
    dvals = rr[pos] + 1j * ri[pos]
    # eigenvectors of H for these eigenvalues
    ew, ev = np.linalg.eig(H)
    vecs = []
    for lam in dvals:
        c = int(np.argmin(np.abs(ew - lam)))
        vecs.append(V.T @ ev[:, c])
    Z = np.array(vecs).T if vecs else np.zeros((n, 0), complex)
    # mimic scipy's post-processing
    nret = nconv
    d = np.zeros(k + 1, complex)
    z = np.zeros((n, k + 1), complex)
    d[:nconv] = dvals
    z[:, :nconv] = Z
    i = 0
    while i <= k:
        if abs(d[i].imag) != 0:
            if i < k:
                i += 1
            else:
                nret -= 1
        i += 1
    if nret <= k:
        d = d[:nret]; z = z[:, :nret]
    else:
        ind = np.argsort(abs(d))[-k:][::-1]
        d = d[ind]; z = z[:, ind]
    return d, z


def _reference(A, k):
    N = A.shape[0]
    v0 = np.ones(N, dtype=A.dtype)
    return sparse.linalg.eigs(A, k=k, v0=v0, maxiter=N * 200, ncv=max(2 * k + 1, 20))


class Solver:
    def solve(self, problem, **kwargs):
        A = problem["matrix"]
        k = problem["k"]
        res = None
        if sparse.isspmatrix_csr(A) or isinstance(A, sparse.csr_array):
            if A.dtype == np.float64 and A.shape[0] > max(2 * k + 1, 20) + 1:
                res = _arpack_like(A, k, max(2 * k + 1, 20))
        if res is None:
            res = _reference(A, k)
        w, v = res
        pairs = list(zip(w, v.T))
        pairs.sort(key=lambda p: -np.abs(p[0]))
        return [p[1] for p in pairs]


# warm up JIT at import
try:
    _A = sparse.random(60, 60, density=0.2, format="csr", random_state=0)
    _arpack_like(_A, 5, 20)
except Exception:
    pass
